<section class="fl-contact-form">
  <div class="fl-container grid">
    <div class="copy">
      <p class="fl-eyebrow">contact</p>
      <h2 class="fl-title">talk to a person</h2>
      <p class="fl-lead">We answer within one working day.</p>
      <ul>
        <li><svg class="fl-px" viewBox="0 0 8 6" aria-hidden="true"><path d="M0 0h1v1h-1zM1 0h1v1h-1zM2 0h1v1h-1zM3 0h1v1h-1zM4 0h1v1h-1zM5 0h1v1h-1zM6 0h1v1h-1zM7 0h1v1h-1zM0 1h1v1h-1zM1 1h1v1h-1zM6 1h1v1h-1zM7 1h1v1h-1zM0 2h1v1h-1zM2 2h1v1h-1zM5 2h1v1h-1zM7 2h1v1h-1zM0 3h1v1h-1zM3 3h1v1h-1zM4 3h1v1h-1zM7 3h1v1h-1zM0 4h1v1h-1zM7 4h1v1h-1zM0 5h1v1h-1zM1 5h1v1h-1zM2 5h1v1h-1zM3 5h1v1h-1zM4 5h1v1h-1zM5 5h1v1h-1zM6 5h1v1h-1zM7 5h1v1h-1z" /></svg><a href="#">hi@example.com</a></li>
        <li><svg class="fl-px" viewBox="0 0 8 7" aria-hidden="true"><path d="M0 0h1v1h-1zM1 0h1v1h-1zM2 0h1v1h-1zM3 0h1v1h-1zM4 0h1v1h-1zM5 0h1v1h-1zM6 0h1v1h-1zM7 0h1v1h-1zM0 1h1v1h-1zM7 1h1v1h-1zM0 2h1v1h-1zM2 2h1v1h-1zM3 2h1v1h-1zM5 2h1v1h-1zM7 2h1v1h-1zM0 3h1v1h-1zM7 3h1v1h-1zM0 4h1v1h-1zM1 4h1v1h-1zM2 4h1v1h-1zM3 4h1v1h-1zM4 4h1v1h-1zM5 4h1v1h-1zM6 4h1v1h-1zM7 4h1v1h-1zM1 5h1v1h-1zM2 5h1v1h-1zM1 6h1v1h-1z" /></svg><a href="#">live chat, 9 to 6</a></li>
        <li><svg class="fl-px" viewBox="0 0 7 7" aria-hidden="true"><path d="M2 0h1v1h-1zM3 0h1v1h-1zM4 0h1v1h-1zM1 1h1v1h-1zM3 1h1v1h-1zM5 1h1v1h-1zM0 2h1v1h-1zM1 2h1v1h-1zM2 2h1v1h-1zM3 2h1v1h-1zM4 2h1v1h-1zM5 2h1v1h-1zM6 2h1v1h-1zM0 3h1v1h-1zM3 3h1v1h-1zM6 3h1v1h-1zM0 4h1v1h-1zM1 4h1v1h-1zM2 4h1v1h-1zM3 4h1v1h-1zM4 4h1v1h-1zM5 4h1v1h-1zM6 4h1v1h-1zM1 5h1v1h-1zM3 5h1v1h-1zM5 5h1v1h-1zM2 6h1v1h-1zM3 6h1v1h-1zM4 6h1v1h-1z" /></svg><span>Placeholder City, Country</span></li>
      </ul>
    </div>
    <form class="form" action="#">
      <div class="two">
        <label class="fl-field" for="fl-contact-name">Name<input class="fl-input" id="fl-contact-name" type="text" autocomplete="name" placeholder="Name Surname" required /></label>
        <label class="fl-field" for="fl-contact-email">Email<input class="fl-input" id="fl-contact-email" type="email" autocomplete="email" placeholder="you@example.com" required /></label>
      </div>
      <label class="fl-field" for="fl-contact-topic">Topic<select class="fl-input" id="fl-contact-topic"><option>Sales</option><option>Support</option><option>Press</option></select></label>
      <label class="fl-field" for="fl-contact-message">Message<textarea class="fl-input" id="fl-contact-message" rows="5" placeholder="How can we help?" required></textarea></label>
      <button class="fl-btn fl-btn--primary" type="submit">send message <svg class="fl-px" viewBox="0 0 7 5" aria-hidden="true"><path d="M4 0h1v1h-1zM5 1h1v1h-1zM0 2h1v1h-1zM1 2h1v1h-1zM2 2h1v1h-1zM3 2h1v1h-1zM4 2h1v1h-1zM5 2h1v1h-1zM6 2h1v1h-1zM5 3h1v1h-1zM4 4h1v1h-1z" /></svg></button>
    </form>
  </div>
</section>

<style>
